```js
async function attempt(fn, retriesLeft = 5) {
  try {
    return await fn();
  } catch (err) {
    if (err.status >= 400 && err.status < 500) throw err;
    if (retriesLeft <= 0) throw err;
    const backoff = Math.min(1000 * 2 ** (5 - retriesLeft), 16000);
    const jitter = Math.random() * 300;
    await sleep(backoff + jitter);
    return attempt(fn, retriesLeft - 1);
  }
}
```

